WITH recent_orders AS (SELECT * FROM orders WHERE amount BETWEEN 550 AND 1120), channel_summary AS (SELECT channel, CASE WHEN discount >= 0.41 THEN 'high' WHEN discount >= 0.08 THEN 'mid' ELSE 'low' END AS discount_bucket, MIN(discount) AS min_discount, MAX(amount) - MIN(amount) AS amount_range FROM recent_orders GROUP BY channel, CASE WHEN discount >= 0.41 THEN 'high' WHEN discount >= 0.08 THEN 'mid' ELSE 'low' END) SELECT channel, discount_bucket, min_discount, amount_range FROM channel_summary WHERE amount_range > 31 ORDER BY amount_range DESC;
